import React, { useEffect, useState } from 'react';
import { getAssociatedFranchises, fetchDurationOptions, createUserExamData } from '../services/api';

const AssociatedFranchises = () => {
  const [examData, setExamData] = useState({
    franchiseId: '',
    examName: '',
    date: '',
    durationInMinutes: '',
    status: 'inprogress',
  });
  const [franchiseList, setFranchiseList] = useState([]);
  const [durationList, setDurationList] = useState([]);
  const [error, setError] = useState(null);
  const [success, setSuccess] = useState('');
  const [loading, setLoading] = useState(false);
  const [userName, setUserName] = useState('');

  const validExamNames = [
    'ServiceNow: CAD', 'ServiceNow: CSA', 'ServiceNow: Platform Developer',
    'ServiceNow: HR AND IMPLEMENTATION', 'ServiceNow: CLOUD ARCHITECTURE',
    'Salesforce developer', 'Salesforce administrators', 'Google cloud', 
    'Mulesoft', 'Fusion'
  ];

  const validStatuses = ['complete', 'absent', 'inprogress'];

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      try {
        const [franchiseData, durationData] = await Promise.all([
          getAssociatedFranchises(),
          fetchDurationOptions()
        ]);
        
        console.log('Fetched franchiseData:', franchiseData);
    console.log('Fetched durationData:', durationData);
        
        if (!Array.isArray(franchiseData) || franchiseData.length === 0) {
          throw new Error('No associated franchises found for the user.');
        }
        
        if (!Array.isArray(durationData.options) || durationData.options.length === 0) {
          throw new Error('No exam durations available.');
        }

        setFranchiseList(franchiseData[0]);
        setDurationList(durationData.options); // Make sure to handle the data structure correctly
        setExamData((prevData) => ({
          ...prevData,
          franchiseId: franchiseData[0]._id || '',
        }));
      } catch (error) {
        console.error('Error fetching data:', error);
        setError(error.message || 'Failed to fetch data.');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const handleExamDataChange = (e) => {
    setExamData({
      ...examData,
      [e.target.name]: e.target.value,
    });
  };

  const handleUserNameChange = (e) => {
    setUserName(e.target.value);
  };

  const validateForm = () => {
    if (!examData.examName || !validExamNames.includes(examData.examName)) {
      return 'Please select a valid exam name.';
    }
    if (!examData.status || !validStatuses.includes(examData.status.toLowerCase())) {
      return 'Please select a valid status.';
    }
    if (!examData.date) {
      return 'Please provide the exam date.';
    }
    const examDate = new Date(examData.date);
    if (isNaN(examDate.getTime())) {
      return 'Invalid date format.';
    }
    if (isNaN(examData.durationInMinutes) || examData.durationInMinutes <= 0) {
      return 'Please select a valid exam duration.';
    }
    return null;
  };

  const handleCreateExamData = async (e) => {
    e.preventDefault();

    const validationError = validateForm();
    if (validationError) {
      setError(validationError);
      return;
    }

    setLoading(true);
    try {
      const formattedDate = new Date(examData.date).toISOString().split('T')[0];
      const payload = {
        franchiseId: examData.franchiseId,
        examData: [{
          name: userName,
          examName: examData.examName,
          date: formattedDate,
          durationInMinutes: examData.durationInMinutes,
          status: examData.status.toLowerCase(),
        }],
      };

      await createUserExamData(payload);
      setSuccess('Exam data created successfully!');
      setExamData({
        franchiseId: examData.franchiseId,
        examName: '',
        date: '',
        durationInMinutes: '',
        status: 'inprogress',
      });
      setError(null);
      setUserName('');
    } catch (error) {
      console.error('Error creating exam data:', error);
      setError(error.message || 'Failed to create exam data.');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (success) {
      const timer = setTimeout(() => setSuccess(''), 3000);
      return () => clearTimeout(timer);
    }
  }, [success]);

  return (
    <div style={styles.container}>
      <h2 style={styles.header}>Associated Franchise</h2>

      {loading && <p style={styles.loading}>Loading...</p>}
      {error && <p style={styles.error}>{error}</p>}
      {success && <p style={styles.success}>{success}</p>}

      <h3 style={styles.formTitle}>Create Exam Data</h3>
      <form onSubmit={handleCreateExamData} style={styles.form}>
        {/* Franchise Select */}
        <div style={styles.formGroup}>
          <label htmlFor="franchiseId" style={styles.label}>Select Franchise</label>
          <select
            name="franchiseId"
            value={examData.franchiseId}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="">Select a franchise</option>
            {franchiseList.map((franchise) => (
              <option key={franchise._id} value={franchise._id}>
                {franchise.name}
              </option>
            ))}
          </select>
        </div>

        {/* User Name */}
        <div style={styles.formGroup}>
          <label htmlFor="userName" style={styles.label}>Name</label>
          <input
            type="text"
            name="userName"
            value={userName}
            onChange={handleUserNameChange}
            required
            style={styles.input}
          />
        </div>

        {/* Exam Name */}
        <div style={styles.formGroup}>
          <label htmlFor="examName" style={styles.label}>Exam Name</label>
          <select
            name="examName"
            value={examData.examName}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="">Select an exam</option>
            {validExamNames.map((exam, index) => (
              <option key={index} value={exam}>{exam}</option>
            ))}
          </select>
        </div>

        {/* Exam Date */}
        <div style={styles.formGroup}>
          <label htmlFor="date" style={styles.label}>Exam Date</label>
          <input
            type="date"
            name="date"
            value={examData.date}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          />
        </div>

        {/* Duration */}
        <div style={styles.formGroup}>
          <label htmlFor="durationInMinutes" style={styles.label}>Duration (Minutes)</label>
          <select
            name="durationInMinutes"
            value={examData.durationInMinutes}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="">Select duration</option>
            {durationList.map((duration) => (
              <option key={duration} value={duration}>
                {duration} minutes
              </option>
            ))}
          </select>
        </div>

        {/* Status */}
        <div style={styles.formGroup}>
          <label htmlFor="status" style={styles.label}>Status</label>
          <select
            name="status"
            value={examData.status}
            onChange={handleExamDataChange}
            required
            style={styles.input}
          >
            <option value="inprogress">In Progress</option>
            <option value="complete">Complete</option>
            <option value="absent">Absent</option>
          </select>
        </div>

        <button type="submit" disabled={loading} style={styles.submitButton}>
          {loading ? 'Submitting...' : 'Create Exam Data'}
        </button>
      </form>
    </div>
  );
};

const styles = {
  container: {
    padding: '20px',
    backgroundColor: '#f8f9fa',
    minHeight: '100vh',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
  },
  header: {
    fontSize: '2rem',
    textAlign: 'center',
    marginBottom: '20px',
  },
  formTitle: {
    fontSize: '1.5rem',
    marginBottom: '15px',
    textAlign: 'center',
  },
  form: {
    width: '100%',
    maxWidth: '500px',
    padding: '20px',
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0 4px 8px rgba(0, 0, 0, 0.1)',
  },
  formGroup: {
    marginBottom: '15px',
  },
  label: {
    display: 'block',
    marginBottom: '8px',
    fontSize: '1rem',
  },
  input: {
    width: '100%',
    padding: '10px',
    fontSize: '1rem',
    border: '1px solid #ccc',
    borderRadius: '4px',
    boxSizing: 'border-box',
  },
  submitButton: {
    width: '100%',
    padding: '12px',
    backgroundColor: '#007bff',
    color: 'white',
    border: 'none',
    borderRadius: '5px',
    cursor: 'pointer',
    fontSize: '1.1rem',
    transition: 'background-color 0.3s ease',
  },
  loading: {
    textAlign: 'center',
    fontSize: '1.2rem',
    color: '#007bff',
  },
  error: {
    color: 'red',
    fontSize: '1.1rem',
    textAlign: 'center',
  },
